	os_memset(&s_yuv_buf, 0, sizeof(s_yuv_buf));
	bk_int_isr_register(INT_SRC_YUVB, yuv_buf_isr, NULL);
	yuv_buf_hal_init(&s_yuv_buf.hal);
	s_yuv_buf_driver_is_init = true;

	return BK_OK;
