{
	if (!s_yuv_buf_driver_is_init) {
		return BK_OK;
	}
	bk_int_isr_unregister(INT_SRC_YUVB);
	yuv_buf_deinit_common();
	os_memset(&s_yuv_buf, 0, sizeof(s_yuv_buf));
	s_yuv_buf_driver_is_init = false;

	return BK_OK;
}

